// Des: Crawl the live site read-only, store every named control, report gaps
// Flo: list each distinct job page > visit > read the accessibility tree > store role + name rows > per job: are its labels on the page? > OK or GAP > summary
// I/O: Ctx (caller) > rows in the state db (mapz), lines on stdout; counts of pages, controls, ok, gaps
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const jobs = @import("ru-jobs-tabl.zig"); const jrun = @import("ru-jobs-main.zig"); const pack = @import("ut-loca-pack.zig"); const priv = @import("ru-safe-priv.zig"); const fld = @import("ut-text-fold.zig");
const CF = .{ .maxn = 800 };
pub const Sum = struct { pages: u32 = 0, controls: u32 = 0, okay: u32 = 0, gaps: u32 = 0 };
const Row = struct { role: []const u8, name: []const u8 };
fn valOf(valu: ?std.json.Value) []const u8 { const vv = valu orelse return ""; if (vv != .object) return ""; const inn = vv.object.get("value") orelse return ""; return if (inn == .string) inn.string else ""; }
fn axRows(ctx: *task.Ctx) ![]const Row { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const res = try ctx.page.call(ctx.aren, "Accessibility.getFullAXTree", ""); const nodes = res.object.get("nodes") orelse return error.CdpError; var out: std.ArrayList(Row) = .empty; for (nodes.array.items) |nod| { if (out.items.len >= CF.maxn) break; if (nod != .object) continue; if (nod.object.get("ignored")) |ign| { if (ign == .bool and ign.bool) continue; } const nam = valOf(nod.object.get("name")); if (nam.len == 0) continue; try out.append(ctx.aren, .{ .role = valOf(nod.object.get("role")), .name = try priv.redact(ctx.aren, nam) }); } return out.items; }
fn onPage(ctx: *task.Ctx, rows: []const Row, labs: []const []const u8) !bool { var all: std.ArrayList(u8) = .empty; for (rows) |rw| { try all.appendSlice(ctx.aren, rw.name); try all.append(ctx.aren, '\n'); } return fld.matchAny(ctx.aren, all.items, labs); }
fn seen(list: []const []const u8, path: []const u8) bool { for (list) |ite| { if (std.mem.eql(u8, ite, path)) return true; } return false; }
pub fn mapRun(ctx: *task.Ctx) !Sum { const prev = ctx.auth; ctx.auth = true; defer ctx.auth = prev; var sum: Sum = .{}; var done: std.ArrayList([]const u8) = .empty; for (&jobs.JOBS) |*jb| { if (jb.path.len == 0) continue; const path = try jrun.pathOf(ctx, jb, .{}); if (seen(done.items, path)) continue; try done.append(ctx.aren, path); task.visit(ctx, path) catch |err| { task.say(ctx, "GAP     page {s}: {s}", .{ path, @errorName(err) }); sum.gaps += 1; continue; }; const rows = axRows(ctx) catch |err| { task.say(ctx, "GAP     page {s}: {s}", .{ path, @errorName(err) }); sum.gaps += 1; continue; }; sum.pages += 1; sum.controls += @intCast(rows.len); ctx.store.mapClear(path) catch {}; const now = task.nowMs(ctx); for (rows) |rw| ctx.store.mapAdd(path, rw.role, rw.name, now) catch {}; for (&jobs.JOBS) |*other| { if (other.path.len == 0) continue; const opath = try jrun.pathOf(ctx, other, .{}); if (!std.mem.eql(u8, opath, path)) continue; for (other.steps) |tpl| { if (tpl.key.len == 0 or tpl.op == .expect) continue; const labs = pack.lab(ctx.conf, tpl.key); if (try onPage(ctx, rows, labs)) { sum.okay += 1; } else { sum.gaps += 1; task.say(ctx, "GAP     {s}: {s} not on {s}", .{ other.name, tpl.key, path }); } } } } task.say(ctx, "map: {d} pages, {d} controls, {d} ok, {d} gaps", .{ sum.pages, sum.controls, sum.okay, sum.gaps }); return sum; }
